#!/usr/bin/env node
// Writes src/plan.generated.ts from docs/commands-plan.json (itself generated by scripts/gen-plan.py from
// docs/commands-plan.src.txt and docs/menus-plan.src.txt). The app reads the plan for the ribbon tabs and
// groups, each command's label, default shortcuts and "not in tabs" flag, the Home tab, and every classic
// menu layout, so the registry, the ribbon and the menu bar can never drift from the plan.
// Run: node scripts/gen-plan-ts.mjs   (also run before dev, build, typecheck and test; a unit test checks it is current)
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const plan = JSON.parse(readFileSync(join(root, 'docs/commands-plan.json'), 'utf8'));

/** "Ctrl+Shift+O" (the plan's notation) -> "Mod-Shift-o" (src/util/keys.ts canonical form); null when not a single key. */
export function planKey(k) {
  const s = String(k).trim();
  if (!s || /…|wheel/.test(s)) return null;
  const parts = s.split('+').map((p) => p.trim());
  // "+" itself: the plan writes zoom in as "+", which splits into ["", ""].
  if (parts.every((p) => p === '')) return s === '+' ? '=' : null;
  const base = parts.pop();
  const names = { Space: 'Space', Backspace: 'Backspace', PgDn: 'PageDown', PgUp: 'PageUp', Right: 'ArrowRight', Left: 'ArrowLeft', Up: 'ArrowUp', Down: 'ArrowDown', Home: 'Home', End: 'End', Enter: 'Enter', Esc: 'Escape', Del: 'Delete', Tab: 'Tab', Ins: 'Insert' };
  const key = names[base] || (base.length === 1 ? base.toLowerCase() : base);
  const mods = parts.map((p) => ({ Ctrl: 'Mod', Cmd: 'Mod', Alt: 'Alt', Shift: 'Shift' }[p] || p));
  const order = ['Mod', 'Alt', 'Shift'];
  return [...order.filter((m) => mods.includes(m)), key].join('-');
}

/** Extra bindings the keyboard produces for a plan key (Shift+= also types "+" on US layouts). */
function keysFor(shortcuts) {
  const out = [];
  for (const s of shortcuts) {
    const k = planKey(s);
    if (!k) continue;
    out.push(k);
    if (s === '+') out.push('Shift-=');
  }
  return [...new Set(out)];
}

const q = (s) => JSON.stringify(s);
const lines = [];
lines.push('/* Generated by scripts/gen-plan-ts.mjs from docs/commands-plan.json. Do not edit; run `npm run plan`. */');
lines.push('');
lines.push('export interface PlanCommand { label: string; keys: string[]; shortcuts: string[]; tab: string; group: string; notInTabs: boolean; origins: string[]; notes: string }');
lines.push('export interface PlanGroup { name: string; commands: string[] }');
lines.push('export interface PlanTab { prefix: string; name: string; description: string; groups: PlanGroup[] }');
lines.push('export type PlanMenuItem = string | { submenu: string; items: PlanMenuItem[] };');
lines.push('export interface PlanMenu { name: string; items: PlanMenuItem[] }');
lines.push('export interface PlanLayout { name: string; modeledOn: string; menus: PlanMenu[] }');
lines.push('');
lines.push('export const PLAN_TABS: PlanTab[] = ' + q(plan.tabs) + ';');
lines.push('');
lines.push('export const PLAN_HOME_TAB: { group: string; commands: string[] }[] = ' + q(plan.homeTab) + ';');
lines.push('');
lines.push('export const PLAN_ORIGINS: Record<string, { name: string; kind: string }> = ' + q(plan.origins) + ';');
lines.push('');
const cmds = {};
for (const [id, c] of Object.entries(plan.commands)) cmds[id] = { label: c.label, keys: keysFor(c.shortcuts), shortcuts: c.shortcuts, tab: c.tab, group: c.group, notInTabs: !!c.notInTabs, origins: c.origins, notes: c.notes };
lines.push('export const PLAN_COMMANDS: Record<string, PlanCommand> = ' + q(cmds) + ';');
lines.push('');
lines.push('export const PLAN_LAYOUTS: Record<string, PlanLayout> = ' + q(plan.menuLayouts) + ';');
lines.push('');
lines.push(`export const PLAN_COMMAND_COUNT = ${Object.keys(plan.commands).length};`);
lines.push('');
const out = lines.join('\n') + '\n';
const target = join(root, 'src/plan.generated.ts');
if (process.argv.includes('--check')) {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== out) { console.error('src/plan.generated.ts is out of date: run node scripts/gen-plan-ts.mjs'); process.exit(1); }
  console.log('src/plan.generated.ts is current');
} else {
  if (!existsSync(target) || readFileSync(target, 'utf8') !== out) { writeFileSync(target, out); console.log(`wrote src/plan.generated.ts (${Object.keys(plan.commands).length} commands, ${Object.keys(plan.menuLayouts).length} layouts)`); }
}
